// Fills every number on the page from data/site_numbers.js (generated by
// R/09_site_numbers.R from the result files). No number is typed into the
// pages: an element with data-n="group.key" shows that value, and an element
// with data-bar="part/whole" is drawn as a share of the whole. An element with
// data-zero-of="group.key" gets the class is-zero when that value is 0, so the
// page shows "none" instead (as the explorer's charts do).
(function () {
  var N = window.SITE_NUMBERS;
  function get(path) {
    return path.split(".").reduce(function (o, k) { return o == null ? undefined : o[k]; }, N);
  }
  function fmt(v) {
    if (typeof v === "number") return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return String(v);
  }
  function each(sel, fn) { Array.prototype.forEach.call(document.querySelectorAll(sel), fn); }
  if (!N) {
    console.error("site_numbers.js did not load: numbers cannot be shown.");
    return;
  }
  each("[data-n]", function (el) {
    var v = get(el.getAttribute("data-n"));
    if (v === undefined) { console.error("Missing number: " + el.getAttribute("data-n")); return; }
    el.textContent = fmt(v);
  });
  each("[data-bar]", function (el) {
    var p = el.getAttribute("data-bar").split("/");
    var part = get(p[0]), whole = get(p[1]);
    if (typeof part !== "number" || typeof whole !== "number" || whole <= 0) { console.error("Bad bar: " + p.join("/")); return; }
    el.style.width = (100 * part / whole).toFixed(2) + "%";
    el.style.setProperty("--p", (part / whole).toFixed(4));
  });
  each("[data-zero-of]", function (el) {
    var v = get(el.getAttribute("data-zero-of"));
    if (typeof v !== "number") { console.error("Bad zero check: " + el.getAttribute("data-zero-of")); return; }
    el.classList.toggle("is-zero", v === 0);
  });
  // web maps: on a narrow screen the map keeps a readable size and scrolls
  // sideways; start with Melton town in view
  function startMaps() {
    each(".map-scroll[data-start]", function (el) {
      var room = el.scrollWidth - el.clientWidth;
      if (room > 0) el.scrollLeft = Math.round(room * parseFloat(el.getAttribute("data-start")));
    });
  }
  if (document.readyState === "complete") startMaps(); else window.addEventListener("load", startMaps);
})();
